import sys

def is_prime(n):
    """判断一个整数是否为素数。"""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    # 只需检查到 sqrt(n)，且只需检查 6k±1 形式的数
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def main():
    if len(sys.argv) != 2:
        print("用法：python3 prime.py <整数>")
        sys.exit(1)

    try:
        n = int(sys.argv[1])
    except ValueError:
        print("错误：请输入一个整数")
        sys.exit(1)

    if is_prime(n):
        print("prime")
    else:
        print("composite")

if __name__ == "__main__":
    main()
```

